package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement on the sheet's today: their due-total now (the figures of their claims that count
 * added up; n/a when their grade has no rate today and no counting claim keeps a figure), and binds every claim of
 * theirs that counts to the figure it has now; one that does not count is unbound (live again).
 */
public class TakeStatement {
    public void take(@Val Person person, @Val StatementTaker taker, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, StatementRepository statements, Out<Statement> taken) {
        String sheetId = person.sheetId();
        var today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        List<Claim> mine = claims.list(sheetId).stream().filter((c) -> c.personId() == person.id()).toList();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        for (Claim c : mine) {
            if (!ClaimDue.counts(c)) {
                claims.bind(c, false, null);
                continue;
            }
            BigDecimal figure = ClaimDue.figure(c, person.grade(), rates, floor);
            kept |= ClaimDue.kept(c);
            if (figure != null) {
                total = total.add(figure);
            }
            counted++;
            claims.bind(c, true, figure);
        }
        String dueTotal = rates.find(sheetId, person.grade(), today) == null && !kept ? "n/a" : total.toPlainString();
        Statement statement = new Statement(sheetId, person.id(), today, dueTotal, counted, taker.by());
        statements.add(statement);
        taken.set(statement);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes an open period, fixing its due-total as it is now: the figures of the claims that count (a held person's OPEN claims do not) whose date falls
 *  in it, added up (skipping n/a). Closing a period already closed is refused. */
public class ClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates, SettingRepository settings,
            Out<PeriodClose> closed)
            throws InvalidPeriodException {
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        Map<Long, Person> byId = people.list(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, (p) -> p));
        BigDecimal floor = settings.floor(period.sheetId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(period.sheetId())) {
            Person person = byId.get(c.personId());
            if (!ClaimDue.countsLive(c, person != null && person.held()) || c.date().isBefore(period.from()) || c.date().isAfter(period.to())) {
                continue;
            }
            BigDecimal figure = person == null ? c.due() : ClaimDue.figure(c, person.grade(), rates, floor);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        if (!periods.close(period, total)) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        closed.set(new PeriodClose(request.by(), total));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED, DRAFT or OPEN to VOID. A voided claim keeps
 * its number (never given again). Settling fixes the claim's due: its amount at its
 * person's grade's rate in force on the claim's date, rounded half to even to two decimals and at least the sheet's floor (left live when no rate applies),
 * or the figure a statement bound it to.
 * Opening records who opened the claim; that user cannot settle it (four eyes). A claim dated inside a closed
 * period cannot change status. A clerk (any user not made a steward) settles only a claim whose due is at or below the
 * sheet's clerk limit, if it has one; a due of n/a is within any limit. A steward settles anything.
 */
public class ApplyClaimStatus {
    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
            PeriodRepository periods, SettingRepository settings, RoleRepository roles, Out<Claim> changed, Out<ClaimNumber> number) throws InvalidClaimStatusException {
        boolean allowed = switch (change.to()) {
            case OPEN -> claim.status() == ClaimStatus.DRAFT;
            case SETTLED -> claim.status() == ClaimStatus.OPEN;
            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
        }
        if (periods.closedOn(claim.sheetId(), claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
        if (change.to() == ClaimStatus.SETTLED && change.by().equals(claim.openedBy())) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it");
        }
        BigDecimal settledDue = change.to() == ClaimStatus.SETTLED ? due(claim, people, rates, settings) : claim.due();
        if (change.to() == ClaimStatus.SETTLED && settledDue != null
                && !RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), change.by()))) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && settledDue.compareTo(limit) > 0) {
                throw new InvalidClaimStatusException("A clerk cannot settle a claim whose due is above the clerk limit");
            }
        }
        number.set(new ClaimNumber(claim.number()));
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), change.to(), claim.number(), settledDue,
                change.to() == ClaimStatus.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue()));
    }

    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings) {
        if (claim.stated()) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : ClaimDue.live(claim, person.grade(), rates, settings.floor(claim.sheetId()));
    }
}

